  .hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background: url('https://arcadia-tour.com/wp-content/uploads/2026/06/arcadia-hero-happy-tourists.jpg') center/cover no-repeat;
    opacity: 0.15;
  }

  .hero-pattern {
    position: absolute;
    inset: 0;
    background-image: radial-gradient(circle at 20% 50%, rgba(201,168,76,0.15) 0%, transparent 50%),
                      radial-gradient(circle at 80% 20%, rgba(201,168,76,0.1) 0%, transparent 40%);
