  .hero-content {
    position: relative;
    z-index: 2;
    max-width: 900px;
  }

  .hero-badge {
    display: inline-block;
    background: rgba(201,168,76,0.2);
    border: 1px solid rgba(201,168,76,0.5);
    color: var(--gold-light);
    padding: 8px 24px;
    border-radius: 50px;
    font-size: 14px;
    letter-spacing: 2px;
    margin-bottom: 24px;
    animation: fadeDown 0.8s ease;
  }

  .hero h1 {
    font-size: clamp(2.5rem, 6vw, 5rem);
    font-weight: 900;
    color: var(--white);
    line-height: 1.2;
    margin-bottom: 20px;
    animation: fadeUp 0.8s ease 0.2s both;
  }

  .hero h1 span {
    color: var(--gold);
    display: block;
  }

  .hero p {
    font-size: clamp(1rem, 2vw, 1.3rem);
    color: rgba(255,255,255,0.8);
    max-width: 600px;
    margin: 0 auto 40px;
    line-height: 1.8;
    animation: fadeUp 0.8s ease 0.4s both;
  }

  .hero-btns {
    display: flex;
    gap: 16px;
    justify-content: center;
    flex-wrap: wrap;
    animation: fadeUp 0.8s ease 0.6s both;
  }

  .btn-primary {
    background: var(--gold);
    color: var(--dark);
    padding: 16px 40px;
    border-radius: 50px;
    font-size: 1.1rem;
